/* NAUKA OD A DO Z — FIX43 KNOWLEDGE SUITE + SITE FEEDBACK
 * Local-first educational tools. Optional serial access is READ ONLY. No device commands are sent.
 */
(() => {
  'use strict';
  const BUILD = '6.8.0-fix43';
  const ROOT = document.getElementById('f43Stage');
  const PAGE = document.getElementById('view-fix43');
  const FEEDBACK_PAGE = document.getElementById('view-feedback');
  const STATUS = document.getElementById('f43Status');
  const FEEDBACK_STATUS = document.getElementById('f43FeedbackStatus');
  const STORE = 'npNaukaKnowledgeFix43';
  const FEEDBACK_STORE = 'npNaukaSiteFeedbackFix43';
  const DB_NAME = 'np-nauka-fix43-documents';
  const DB_STORE = 'documents';
  const MAX_DOC = 20 * 1024 * 1024;
  const MAX_BACKUP_DOCS = 15 * 1024 * 1024;
  const $ = (s, root = PAGE) => root?.querySelector(s) || null;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clean = (value, max = 1000) => String(value ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim().slice(0, max);
  const now = () => new Date().toISOString();
  const uid = prefix => `${prefix}-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;
  const parse = (raw, fallback) => { try { return JSON.parse(raw); } catch { return fallback; } };
  const fmt = n => new Intl.NumberFormat('pl-PL', {maximumFractionDigits:2}).format(Number(n || 0));
  const CASES = [
    {id:'no-power',label:'Brak reakcji na Power',keys:['nie uruchamia','brak reakcji','nie reaguje','no power','nie startuje'],hypotheses:['Problem z zasilaczem lub przewodem wejściowym.','Przerwa w torze wejściowym, bezpieczniku lub MOSFET-ach.','Brak sygnału sterującego EC albo nieprawidłowa sekwencja zasilania.'],steps:['Zweryfikuj zasilacz i parametry wejściowe poza płytą.','Odczytaj Board ID oraz rewizję i znajdź właściwy schemat.','Po odłączeniu zasilania wykonaj oględziny i bezpieczne pomiary rezystancji.','Pomiary napięć wykonuj dopiero po określeniu punktów i warunków z dokumentacji.'],confidence:0.62},
    {id:'black-screen',label:'Czarny ekran / brak obrazu',keys:['czarny ekran','brak obrazu','black screen','nie ma obrazu'],hypotheses:['Problem z matrycą, taśmą lub podświetleniem.','Brak POST, pamięć RAM lub firmware.','Tor GPU / wyjścia obrazu albo zasilanie ekranu.'],steps:['Sprawdź zachowanie diod, wentylatorów i sygnałów POST.','Zweryfikuj obraz na zewnętrznym monitorze.','Porównaj wariant panelu i złącza z dokumentacją dokładnego modelu.','Nie wymieniaj GPU ani BIOS bez potwierdzenia testami.'],confidence:0.58},
    {id:'charging',label:'Nie ładuje baterii',keys:['nie ładuje','ładowanie','charging','bateria nie'],hypotheses:['Zasilacz, przewód lub złącze wejściowe.','Kontroler ładowania, MOSFET-y wejściowe albo rezystor pomiarowy.','Bateria, jej BMS lub linie komunikacyjne.'],steps:['Zweryfikuj zasilacz i obsługiwany profil PD.','Sprawdź stan portu i baterii bez ingerencji w ogniwa.','Znajdź tor wejścia i kontroler ładowania w schemacie rewizji.','Pomiary pod napięciem wykonuj tylko według instrukcji serwisowej.'],confidence:0.57},
    {id:'overheat',label:'Przegrzewanie',keys:['przegrzewa','wysoka temperatura','overheat','wyłącza się pod obciążeniem'],hypotheses:['Zabrudzony radiator lub wentylator.','Nieprawidłowy docisk, pasta lub termopady.','Sterowanie wentylatorem, czujnik lub nadmierne obciążenie.'],steps:['Odczytaj temperatury i częstotliwości w spoczynku oraz obciążeniu.','Sprawdź przepływ powietrza i pracę wentylatorów.','Zweryfikuj grubość i położenie termopadów przed montażem.','Po serwisie wykonaj kontrolowany test obciążeniowy.'],confidence:0.68},
    {id:'nvme',label:'Dysk NVMe niewykrywany',keys:['nvme','dysk nie jest wykrywany','nie wykrywa dysku','ssd znik'],hypotheses:['Problem z nośnikiem lub złączem M.2.','Nieprawidłowa konfiguracja BIOS/UEFI albo linie PCIe.','Uszkodzony tor zasilania lub kontroler.'],steps:['Zabezpiecz dane; nie inicjalizuj i nie formatuj nośnika.','Sprawdź nośnik w zgodnym adapterze tylko do odczytu, gdy to możliwe.','Porównaj obsługiwany klucz M.2, długość, protokół i linie PCIe.','Zapisz SMART i logi przed próbą naprawy.'],confidence:0.55},
    {id:'usb',label:'Port USB nie działa',keys:['usb nie działa','port usb','usb-c nie działa'],hypotheses:['Uszkodzenie mechaniczne gniazda lub linii danych.','Zabezpieczenie ESD, przełącznik zasilania lub kontroler.','Problem sterownika albo konfiguracji systemu.'],steps:['Ustal, czy problem występuje w systemie i UEFI.','Sprawdź inne urządzenie i przewód.','Zidentyfikuj kontroler oraz zabezpieczenia na schemacie.','Nie podawaj napięcia na linie danych.'],confidence:0.52}
  ];
  const SIGNALS = [
    ['VIN_PRESENT','Napięcie wejściowe — potwierdź według schematu'],
    ['ACOK','ACOK / informacja o poprawnym wejściu'],
    ['ALW_3V3','Szyna always 3,3 V — wartość z dokumentacji'],
    ['ALW_5V','Szyna always 5 V — jeśli występuje w danej konstrukcji'],
    ['EC_ON','Sygnał załączenia sterowania EC / platformy'],
    ['RSMRST','RSMRST# — stan zgodny z dokumentacją'],
    ['SLP_S5','SLP_S5# — stan zgodny z dokumentacją'],
    ['SLP_S3','SLP_S3# — stan zgodny z dokumentacją'],
    ['VR_ON','Załączenie regulatorów głównych'],
    ['PGOOD','Sygnał Power Good dla odpowiedniej domeny']
  ];
  const SEED_COMPONENTS = [
    {id:'EDU-MOSFET-N',name:'MOSFET N-channel EDU',category:'Tranzystor',package:'SOT-23 / EDU',notes:'Przykład edukacyjny. Dobór wymaga VDS, RDS(on), VGS, SOA i pinoutu.'},
    {id:'EDU-MOSFET-P',name:'MOSFET P-channel EDU',category:'Tranzystor',package:'SOT-23 / EDU',notes:'Przykład edukacyjny. Weryfikuj polaryzację, VGS i parametry dynamiczne.'},
    {id:'EDU-CHARGER',name:'Kontroler ładowania EDU',category:'Układ scalony',package:'QFN / EDU',notes:'Symbol EDU, nie jest numerem katalogowym rzeczywistego producenta.'},
    {id:'EDU-EC',name:'Kontroler EC EDU',category:'Układ scalony',package:'BGA / EDU',notes:'Karta treningowa; nie stanowi mapy pinów konkretnej platformy.'},
    {id:'EDU-CAP',name:'Kondensator ceramiczny EDU',category:'Kondensator',package:'0603 / EDU',notes:'Uwzględnij DC-bias, dielektryk, ESR, napięcie i temperaturę.'},
    {id:'EDU-COIL',name:'Dławik przetwornicy EDU',category:'Dławik',package:'SMD / EDU',notes:'Sprawdź Isat, Irms, DCR, częstotliwość i footprint.'}
  ];
  const blankState = () => ({version:1,diagnoses:[],sequences:[],components:[],documents:[],evidence:[],buildChecks:[],serialReadings:[],updatedAt:now()});
  function normalizeState(value) {
    const out=blankState(); if(!value||typeof value!=='object'||Array.isArray(value)) return out;
    for(const key of ['diagnoses','sequences','components','documents','evidence','buildChecks','serialReadings']) {
      out[key]=Array.isArray(value[key])?value[key].filter(x=>x&&typeof x==='object'&&!Array.isArray(x)).slice(0,200).map(x=>JSON.parse(JSON.stringify(x))):[];
    }
    out.components=out.components.map(x=>({id:clean(x.id,80)||uid('CMP'),name:clean(x.name,120),category:clean(x.category,80),package:clean(x.package,60),notes:clean(x.notes,500),source:clean(x.source,300)})).filter(x=>x.name);
    out.documents=out.documents.map(x=>({id:clean(x.id,80),name:clean(x.name,180),type:clean(x.type,100),size:Math.max(0,Number(x.size)||0),createdAt:clean(x.createdAt,40)})).filter(x=>x.id&&x.name);
    out.updatedAt=clean(value.updatedAt,40)||now(); return out;
  }
  let state=normalizeState(parse(localStorage.getItem(STORE),null));
  function persist(){state.updatedAt=now();localStorage.setItem(STORE,JSON.stringify(state));}
  function setStatus(message,isError=false){if(STATUS){STATUS.textContent=message;STATUS.classList.toggle('is-error',!!isError);STATUS.classList.toggle('is-good',!isError);}}
  const tabs=['overview','doctor','sequence','hardware','documents','components','evidence','compatibility','graph','offline'];
  let activeTab='overview'; let serialPort=null; let serialReader=null; let serialStopped=false;
  function setTab(name){if(!tabs.includes(name))return;activeTab=name;document.querySelectorAll('[data-f43-tab]').forEach(b=>{const active=b.dataset.f43Tab===name;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});render();}
  function doctorTemplate(){return `<div class="f43-grid two"><section class="f43-card"><span class="f43-kicker">SYMPTOM ANALYSIS / RULE-BASED</span><h2>AI Board Doctor — analiza przypadku</h2><p class="f43-muted">Silnik lokalny łączy objawy ze zweryfikowanymi kategoriami przypadków edukacyjnych. Nie analizuje automatycznie obrazu ani nie zgaduje pinów. Zdjęcie i pomiary możesz dołączyć do dowodów naprawy.</p><form id="f43DoctorForm" class="f43-form"><label>Urządzenie<input name="device" maxlength="80" placeholder="Laptop / PC / płyta główna" required></label><label>Model<input name="model" maxlength="140" placeholder="Dokładny model"></label><label>Board ID<input name="boardId" maxlength="100" placeholder="Oznaczenie z laminatu"></label><label>Rewizja<input name="revision" maxlength="50" placeholder="REV 1.0"></label><label class="full">Objaw<textarea name="symptom" required maxlength="800" rows="3" placeholder="Opisz dokładnie, co się dzieje..."></textarea></label><label class="full">Zaobserwowane pomiary / sygnały<textarea name="measurements" maxlength="1000" rows="3" placeholder="Wartości, tryb miernika, stan zasilania i źródło pomiaru..."></textarea></label><button class="f43-btn primary full" type="submit">Przeanalizuj objaw</button></form><div id="f43DoctorResult" aria-live="polite"></div></section><section class="f43-card"><span class="f43-kicker">EVIDENCE / HISTORY</span><h2>Ostatnie analizy</h2><div id="f43DoctorHistory">${renderDiagnosisList()}</div></section></div>`;}
  function renderDiagnosisList(){if(!state.diagnoses.length)return '<p class="f43-muted">Brak zapisanych analiz. Wyniki będą przechowywane lokalnie.</p>';return state.diagnoses.slice(0,8).map(d=>`<article class="f43-list-row"><b>${esc(d.label||'Analiza przypadku')}</b><small>${esc(d.model||'Model niepodany')} · ${esc(d.createdAt||'')}</small><p>${esc(d.symptom||'')}</p><span class="f43-chip">Pewność heurystyczna: ${Math.round((d.confidence||0)*100)}%</span></article>`).join('');}
  function diagnoseBoard(input){const text=`${input.symptom||''} ${input.measurements||''}`.toLocaleLowerCase('pl-PL');const match=CASES.map(c=>({...c,score:c.keys.reduce((n,k)=>n+(text.includes(k)?1:0),0)})).sort((a,b)=>b.score-a.score)[0];if(!match||match.score===0)return {matched:false,label:'Brak dopasowania w lokalnej bazie',hypotheses:['Brak wystarczających danych do wskazania konkretnego przypadku.','Możliwa przyczyna wymaga dokumentacji dokładnego modelu i rewizji.'],steps:['Zapisz dokładny objaw i warunki wystąpienia.','Ustal model, Board ID i rewizję PCB.','Porównaj pomiary z wiarygodną dokumentacją serwisową.'],confidence:0,disclaimer:'To wskazówki edukacyjne, nie diagnoza ani zalecenie wymiany elementu.'};return {matched:true,caseId:match.id,label:match.label,hypotheses:match.hypotheses,steps:match.steps,confidence:match.confidence,disclaimer:'To dopasowanie heurystyczne do przypadku edukacyjnego. Potwierdź wszystkie punkty w dokumentacji konkretnej płyty.'};}
  function sequenceTemplate(){return `<section class="f43-card"><span class="f43-kicker">POWER SEQUENCE / BOARD-SPECIFIC</span><h2>Analizator sekwencji zasilania</h2><p class="f43-muted">Wybierz status sygnałów po odczycie z dokumentacji i pomiarach. Kolejność jest przykładową ścieżką szkoleniową, nie uniwersalnym wymaganiem każdej płyty.</p><form id="f43SequenceForm"><div class="f43-signal-grid">${SIGNALS.map(([id,label],i)=>`<label class="f43-signal"><span><b>${i+1}. ${esc(id)}</b><small>${esc(label)}</small></span><select name="${id}"><option value="unknown">Nie zmierzono</option><option value="ok">Potwierdzono zgodność</option><option value="missing">Brak / niezgodny stan</option></select></label>`).join('')}</div><label class="f43-inline-check"><input type="checkbox" name="boardVerified"> Mam schemat dokładnego modelu i rewizji</label><div class="f43-actions"><button class="f43-btn primary" type="submit">Przeanalizuj sekwencję</button></div></form><div id="f43SequenceResult" aria-live="polite"></div></section><section class="f43-card"><span class="f43-kicker">SEQUENCE HISTORY</span><h2>Zapisane przebiegi</h2><div id="f43SequenceHistory">${state.sequences.slice(0,8).map(x=>`<article class="f43-list-row"><b>${esc(x.summary)}</b><small>${esc(x.createdAt)}</small><p>${esc(x.detail)}</p></article>`).join('')||'<p class="f43-muted">Brak zapisanych przebiegów.</p>'}</div></section>`;}
  function evaluateSequence(input){const sequence=SIGNALS.map(([id])=>({id,status:input[id]||'unknown'}));let firstIssue=sequence.findIndex(x=>x.status==='missing');let unknownBefore=sequence.findIndex(x=>x.status==='unknown');let result;if(firstIssue>=0&&(unknownBefore<0||firstIssue<unknownBefore)){result={level:'warn',summary:`Pierwszy niepotwierdzony etap: ${sequence[firstIssue].id}`,detail:`Zatrzymaj analizę na tym etapie. Potwierdź punkt pomiarowy, masę odniesienia, stan zasilania i poprawność schematu dla tej rewizji. Nie zakładaj, że dalsze sygnały powinny występować w każdej konstrukcji.`};}else if(unknownBefore>=0){result={level:'neutral',summary:`Brakuje pomiaru: ${sequence[unknownBefore].id}`,detail:'Nie wyciągaj wniosku z niezmierzonego sygnału. Uzupełnij pomiary zgodnie z dokumentacją właściwej płyty.'};}else{result={level:'good',summary:'Wszystkie etapy oznaczono jako zgodne',detail:'To nie potwierdza sprawności całej płyty. Sprawdź warunki obciążenia, stabilność sygnałów i wymagania producenta.'};}if(!input.boardVerified)result.detail+=' Uwaga: nie potwierdzono schematu dokładnej rewizji — traktuj wynik tylko jako ćwiczenie.';return {...result,sequence};}
  function hardwareTemplate(){return `<div class="f43-grid two"><section class="f43-card"><span class="f43-kicker">WEB SERIAL / READ ONLY</span><h2>Połączenie z urządzeniem szeregowym</h2><p class="f43-muted">Wspierane wyłącznie w przeglądarkach udostępniających Web Serial w bezpiecznym kontekście. Program nie wysyła bajtów, nie steruje miernikiem ani zasilaczem. Protokół i ustawienia muszą być zgodne z instrukcją producenta.</p><div class="f43-form"><label>Prędkość transmisji<select id="f43Baud"><option>9600</option><option>19200</option><option>38400</option><option>57600</option><option>115200</option></select></label><div class="f43-actions"><button type="button" class="f43-btn primary" id="f43SerialConnect">Wybierz port i rozpocznij odczyt</button><button type="button" class="f43-btn secondary" id="f43SerialStop" disabled>Zatrzymaj odczyt</button></div></div><div id="f43SerialState" class="f43-status">Port nie jest połączony.</div><div id="f43SerialData" class="f43-serial-data">Odebrane linie pojawią się tutaj.</div></section><section class="f43-card"><span class="f43-kicker">DETECTED LINES</span><h2>Rozpoznane wartości tekstowe</h2><div id="f43SerialReadings">${renderSerialReadings()}</div><p class="f43-muted">Parser rozpoznaje wyłącznie proste linie tekstowe z liczbą i jednostką. Nie dekoduje automatycznie protokołów producentów.</p></section></div>`;}
  function renderSerialReadings(){return state.serialReadings.slice(0,12).map(x=>`<div class="f43-list-row"><b>${esc(x.value)} ${esc(x.unit)}</b><small>${esc(x.line)} · ${esc(x.at)}</small></div>`).join('')||'<p class="f43-muted">Brak rozpoznanych wartości.</p>';}
  function parseSerialLine(line){const raw=clean(line,160);const m=raw.match(/(?:^|[^\w])(-?\d+(?:[.,]\d+)?)\s*(mV|V|A|mA|kOhm|kohm|Ohm|ohm|°C|Hz|kHz)\b/i);if(!m)return null;return {value:Number(m[1].replace(',','.')),unit:m[2],line:raw};}
  function docsTemplate(){return `<div class="f43-grid two"><section class="f43-card"><span class="f43-kicker">LOCAL DOCUMENT LIBRARY</span><h2>Dodaj dokumentację</h2><p class="f43-muted">PDF, CSV, JSON, zdjęcia i notatki są przechowywane lokalnie w IndexedDB tej przeglądarki. Nie są wysyłane do serwera.</p><form id="f43DocumentForm" class="f43-form"><label class="full">Plik dokumentacji<input id="f43DocumentFile" type="file" accept=".pdf,.csv,.json,.txt,.jpg,.jpeg,.png,.webp,application/pdf,text/csv,application/json,image/*" required></label><label class="full">Opis / model / Board ID<input name="description" maxlength="220" placeholder="np. Lenovo XXX — Board ID ABC, REV 1.2"></label><button type="submit" class="f43-btn primary full">Zapisz dokument lokalnie</button></form><div id="f43DocumentPreview"></div></section><section class="f43-card"><span class="f43-kicker">OFFLINE FILE INDEX</span><h2>Twoja biblioteka</h2><div id="f43DocumentList">${renderDocumentList()}</div></section></div>`;}
  function renderDocumentList(){if(!state.documents.length)return '<p class="f43-muted">Nie dodano dokumentów. Dodaj własny schemat lub kartę katalogową.</p>';return state.documents.map(d=>`<article class="f43-list-row"><b>${esc(d.name)}</b><small>${fmt(d.size/1024)} KB · ${esc(d.createdAt)}</small><p>${esc(d.description||d.type)}</p><div class="f43-actions"><button type="button" class="f43-btn secondary" data-f43-doc-open="${esc(d.id)}">Otwórz / pobierz</button><button type="button" class="f43-btn secondary" data-f43-doc-delete="${esc(d.id)}">Usuń</button></div></article>`).join('');}
  function componentsTemplate(){return `<div class="f43-grid two"><section class="f43-card"><span class="f43-kicker">COMPONENT INTELLIGENCE</span><h2>Katalog elementów</h2><input class="f43-search" id="f43ComponentSearch" type="search" placeholder="Oznaczenie, funkcja, obudowa…"><div id="f43ComponentList">${renderComponents()}</div></section><section class="f43-card"><span class="f43-kicker">USER CATALOG</span><h2>Dodaj własny element</h2><form id="f43ComponentForm" class="f43-form"><label>Oznaczenie / ID<input name="id" maxlength="80" required placeholder="Pełne oznaczenie producenta"></label><label>Nazwa<input name="name" maxlength="120" required></label><label>Kategoria<input name="category" maxlength="80" placeholder="MOSFET / IC / kondensator"></label><label>Obudowa<input name="package" maxlength="60"></label><label class="full">Uwagi / parametry ze źródła<textarea name="notes" maxlength="600" rows="4"></textarea></label><label class="full">Źródło / datasheet<input name="source" maxlength="300" placeholder="URL https://… lub numer dokumentu"></label><button type="submit" class="f43-btn primary full">Dodaj do lokalnego katalogu</button></form><p class="f43-muted">Katalog nie proponuje automatycznie zamienników. Zgodność wymaga porównania pełnych parametrów i pinoutu z kartami katalogowymi.</p></section></div>`;}
  function renderComponents(q=''){const all=[...SEED_COMPONENTS,...state.components];const filter=clean(q,100).toLowerCase();const filtered=all.filter(x=>`${x.id} ${x.name} ${x.category} ${x.package} ${x.notes}`.toLowerCase().includes(filter));return filtered.map(x=>`<article class="f43-list-row"><b>${esc(x.name)}</b><small>${esc(x.id)} · ${esc(x.category)} · ${esc(x.package)}</small><p>${esc(x.notes)}</p>${x.source?`<small>Źródło: ${esc(x.source)}</small>`:''}</article>`).join('')||'<p class="f43-muted">Brak wyników w katalogu.</p>';}
  function evidenceTemplate(){return `<div class="f43-grid two"><section class="f43-card"><span class="f43-kicker">REPAIR EVIDENCE / LOCAL CASE FILE</span><h2>Dokumentuj naprawę</h2><form id="f43EvidenceForm" class="f43-form"><label>Urządzenie<input name="device" required maxlength="80" placeholder="Laptop / PC / płyta"></label><label>Model<input name="model" required maxlength="140"></label><label>Board ID / rewizja<input name="board" maxlength="120"></label><label>Numer zlecenia<input name="job" maxlength="60" placeholder="opcjonalnie"></label><label class="full">Objaw<input name="symptom" required maxlength="500"></label><label class="full">Diagnoza / wykonane czynności<textarea name="work" rows="4" maxlength="1800" required></textarea></label><label class="full">Części / numery katalogowe<textarea name="parts" rows="2" maxlength="800"></textarea></label><label class="full">Wynik testu końcowego<textarea name="result" rows="3" maxlength="1000"></textarea></label><label class="full">Zdjęcia przed/po (zostaną dodane do lokalnej biblioteki)<input id="f43EvidenceFiles" type="file" accept="image/*,.pdf" multiple></label><button class="f43-btn primary full" type="submit">Zapisz dokumentację naprawy</button></form></section><section class="f43-card"><span class="f43-kicker">CASE HISTORY</span><h2>Raporty lokalne</h2><div id="f43EvidenceList">${renderEvidence()}</div></section></div>`;}
  function renderEvidence(){return state.evidence.slice(0,30).map(x=>`<article class="f43-list-row"><b>${esc(x.device)} — ${esc(x.model)}</b><small>${esc(x.id)} · ${esc(x.createdAt)}</small><p>${esc(x.symptom)}</p><p>${esc(x.result||'Wynik nieuzupełniony')}</p><div class="f43-actions"><button class="f43-btn secondary" type="button" data-f43-evidence-print="${esc(x.id)}">Drukuj / PDF</button><button class="f43-btn secondary" type="button" data-f43-evidence-export="${esc(x.id)}">Pobierz JSON</button></div></article>`).join('')||'<p class="f43-muted">Brak zapisanych raportów napraw.</p>';}
  function compatibilityTemplate(){return `<section class="f43-card"><span class="f43-kicker">HARDWARE COMPATIBILITY MASTER</span><h2>Sprawdź kompatybilność zestawu PC</h2><p class="f43-muted">Wprowadź dane odczytane z instrukcji producentów. Program porównuje wyłącznie podane wartości — nie pobiera automatycznie bazy modeli ani listy obsługiwanych procesorów.</p><form id="f43BuildForm" class="f43-form"><label>Socket procesora<input name="cpuSocket" required placeholder="np. AM5"></label><label>Socket płyty<input name="boardSocket" required placeholder="np. AM5"></label><label>Generacja RAM procesora/płyty<input name="cpuRam" required placeholder="np. DDR5"></label><label>Typ RAM obsługiwany przez płytę<input name="boardRam" required placeholder="np. DDR5"></label><label>Długość GPU (mm)<input type="number" name="gpuLength" min="1" max="1000" required></label><label>Maksymalna długość GPU w obudowie (mm)<input type="number" name="caseLength" min="1" max="1000" required></label><label>Moc zasilacza (W)<input type="number" name="psu" min="1" max="3000" required></label><label>Szacowany pobór zestawu (W)<input type="number" name="draw" min="1" max="2500" required></label><button type="submit" class="f43-btn primary full">Sprawdź kompatybilność</button></form><div id="f43BuildResult" aria-live="polite"></div></section>`;}
  function checkBuild(v){const issues=[],warnings=[];const norm=x=>clean(x,40).replace(/\s+/g,'').toUpperCase();if(norm(v.cpuSocket)!==norm(v.boardSocket))issues.push('Socket CPU i płyty nie są zgodne.');if(norm(v.cpuRam)!==norm(v.boardRam))issues.push('Deklarowany typ pamięci CPU i płyty jest różny.');const gpu=Number(v.gpuLength),clear=Number(v.caseLength),psu=Number(v.psu),draw=Number(v.draw);if(!(gpu>0&&clear>0&&psu>0&&draw>0))issues.push('Wszystkie wymiary i moce muszą być liczbami dodatnimi.');else{if(gpu>clear)issues.push('Karta graficzna jest dłuższa niż zadeklarowany prześwit obudowy.');if(psu<draw*1.25)warnings.push('Zasilacz nie zapewnia orientacyjnego 25% zapasu względem podanego poboru. Zweryfikuj obciążenie, jakość, piki i wymagania GPU.');}return {compatible:issues.length===0,issues,warnings,notice:'Wynik nie sprawdza BIOS/CPU support list, wysokości chłodzenia, złączy zasilania, szerokości GPU, linii PCIe, limitów termicznych ani jakości zasilacza. Sprawdź instrukcje producentów.'};}
  function graphTemplate(){return `<section class="f43-card"><span class="f43-kicker">SMART KNOWLEDGE GRAPH / LOCAL LINKS</span><h2>Mapa powiązań wiedzy</h2><p class="f43-muted">Mapa buduje powiązania z Twoich zapisanych analiz, dokumentów, kart komponentów i raportów. Nie dopisuje niezweryfikowanych zależności między modelami.</p><div class="f43-graph-stats" id="f43GraphStats"></div><div id="f43KnowledgeGraph" class="f43-graph">${renderGraph()}</div></section>`;}
  function renderGraph(){const nodes=[];state.diagnoses.forEach(d=>nodes.push({type:'Objaw',title:d.label||d.symptom,link:d.model||d.boardId||'bez modelu'}));state.documents.forEach(d=>nodes.push({type:'Dokument',title:d.name,link:d.description||d.type}));state.components.forEach(d=>nodes.push({type:'Element',title:d.name,link:d.id}));state.evidence.forEach(d=>nodes.push({type:'Naprawa',title:d.model,link:d.symptom}));return nodes.slice(0,100).map(n=>`<article class="f43-graph-node"><span>${esc(n.type)}</span><b>${esc(n.title)}</b><small>${esc(n.link)}</small></article>`).join('')||'<p class="f43-muted">Mapa powiązań pojawi się po zapisaniu pierwszej analizy, dokumentu, elementu lub raportu.</p>';}
  function offlineTemplate(){return `<div class="f43-grid two"><section class="f43-card"><span class="f43-kicker">OFFLINE PRO 2.0 / AES-GCM</span><h2>Zaszyfruj kopię lokalnych danych</h2><p class="f43-muted">Plik zawiera dane FIX43 oraz dokumenty przechowywane w IndexedDB. Szyfrowanie AES-GCM z kluczem PBKDF2. Hasła nie zapisujemy i nie można go odzyskać.</p><form id="f43BackupForm" class="f43-form"><label class="full">Hasło kopii (min. 12 znaków)<input type="password" name="password" minlength="12" maxlength="200" autocomplete="new-password" required></label><label class="full">Powtórz hasło<input type="password" name="confirm" minlength="12" maxlength="200" autocomplete="new-password" required></label><button type="submit" class="f43-btn primary full">Utwórz zaszyfrowaną kopię .np43</button></form><div id="f43BackupStatus" class="f43-status" aria-live="polite"></div></section><section class="f43-card"><span class="f43-kicker">RESTORE / AES-GCM</span><h2>Odtwórz kopię na tym urządzeniu</h2><form id="f43RestoreForm" class="f43-form"><label class="full">Plik .np43<input type="file" name="backup" accept=".np43,.json,application/json" required></label><label class="full">Hasło kopii<input type="password" name="password" minlength="12" maxlength="200" required autocomplete="current-password"></label><label class="f43-inline-check full"><input type="checkbox" name="replace" required> Zastąp lokalny stan modułu FIX43 danymi z kopii.</label><button type="submit" class="f43-btn primary full">Odszyfruj i przywróć</button></form><div id="f43RestoreStatus" class="f43-status" aria-live="polite"></div></section></div><section class="f43-card"><span class="f43-kicker">OFFLINE INVENTORY</span><h2>Stan zapisanych danych</h2><div id="f43OfflineInventory"></div><p class="f43-muted">Dokumenty lokalne nie są automatycznie synchronizowane z innymi urządzeniami. Aby przenieść je na drugi komputer, utwórz zaszyfrowaną kopię i odtwórz ją tam.</p></section>`;}
  function render(){if(!ROOT)return;const templates={overview:overviewTemplate,doctor:doctorTemplate,sequence:sequenceTemplate,hardware:hardwareTemplate,documents:docsTemplate,components:componentsTemplate,evidence:evidenceTemplate,compatibility:compatibilityTemplate,graph:graphTemplate,offline:offlineTemplate};ROOT.innerHTML=(templates[activeTab]||overviewTemplate)();if(activeTab==='graph'){const el=$('#f43GraphStats');if(el)el.textContent=`${state.diagnoses.length} analiz · ${state.documents.length} dokumentów · ${state.components.length+SEED_COMPONENTS.length} elementów · ${state.evidence.length} raportów`;}if(activeTab==='offline'){const el=$('#f43OfflineInventory');if(el)el.innerHTML=`<div class="f43-stats"><div><b>${state.diagnoses.length}</b><span>analizy</span></div><div><b>${state.documents.length}</b><span>dokumenty</span></div><div><b>${state.components.length+SEED_COMPONENTS.length}</b><span>elementy</span></div><div><b>${state.evidence.length}</b><span>raporty</span></div></div>`;}}
  function overviewTemplate(){return `<div class="f43-stats"><div><b>${state.diagnoses.length}</b><span>analizy diagnostyczne</span></div><div><b>${state.documents.length}</b><span>dokumenty lokalne</span></div><div><b>${state.components.length+SEED_COMPONENTS.length}</b><span>karty komponentów</span></div><div><b>${state.evidence.length}</b><span>raporty napraw</span></div></div><div class="f43-overview-grid"><button type="button" data-f43-open="doctor"><b>AI Board Doctor</b><span>Objawy → hipotezy → bezpieczne kroki</span></button><button type="button" data-f43-open="sequence"><b>Power Sequence Analyzer</b><span>Kontrola kolejności sygnałów na podstawie schematu</span></button><button type="button" data-f43-open="hardware"><b>Real Hardware Connection</b><span>Opcjonalny port szeregowy — wyłącznie odczyt</span></button><button type="button" data-f43-open="documents"><b>Globalna dokumentacja</b><span>PDF, zdjęcia, CSV i JSON w lokalnej bibliotece</span></button><button type="button" data-f43-open="components"><b>Component Intelligence</b><span>Własny katalog i karta elementu</span></button><button type="button" data-f43-open="evidence"><b>Repair Evidence</b><span>Udokumentuj czynności, części i wynik naprawy</span></button><button type="button" data-f43-open="compatibility"><b>Hardware Compatibility</b><span>Kontrola socket, RAM, długości GPU i mocy</span></button><button type="button" data-f43-open="graph"><b>Smart Knowledge Graph</b><span>Powiąż zapisane dane w jedną mapę</span></button><button type="button" data-f43-open="offline"><b>Offline PRO 2.0</b><span>Zaszyfruj i przenieś dane między komputerami</span></button></div><section class="f43-card"><span class="f43-kicker">LATEST ACTIVITY</span><h2>Ostatnia aktywność</h2><div class="f43-recent">${[...state.diagnoses.slice(0,2).map(x=>`<p><b>Diagnoza:</b> ${esc(x.label||x.symptom)}</p>`),...state.evidence.slice(0,2).map(x=>`<p><b>Raport:</b> ${esc(x.model)} — ${esc(x.symptom)}</p>`)].join('')||'<p class="f43-muted">Nie zapisano jeszcze aktywności. Otwórz jeden z modułów powyżej.</p>'}</div></section>`;}
  function openDocDb(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(new Error('Ta przeglądarka nie obsługuje IndexedDB.'));return;}const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(DB_STORE))db.createObjectStore(DB_STORE,{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('Nie można otworzyć lokalnej biblioteki.'));});}
  async function putDoc(doc){const db=await openDocDb();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(doc);tx.oncomplete=()=>{db.close();resolve(true);};tx.onerror=()=>{db.close();reject(tx.error);};});}
  async function getDoc(id){const db=await openDocDb();return new Promise((resolve,reject)=>{const req=db.transaction(DB_STORE,'readonly').objectStore(DB_STORE).get(id);req.onsuccess=()=>{db.close();resolve(req.result||null);};req.onerror=()=>{db.close();reject(req.error);};});}
  async function deleteDoc(id){const db=await openDocDb();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).delete(id);tx.oncomplete=()=>{db.close();resolve(true);};tx.onerror=()=>{db.close();reject(tx.error);};});}
  async function clearDocStore(){if(!('indexedDB' in window))return false;const db=await openDocDb();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).clear();tx.oncomplete=()=>{db.close();resolve(true);};tx.onerror=()=>{db.close();reject(tx.error);};});}
  async function getAllDocs(){if(!('indexedDB' in window))return [];const db=await openDocDb();return new Promise((resolve,reject)=>{const req=db.transaction(DB_STORE,'readonly').objectStore(DB_STORE).getAll();req.onsuccess=()=>{db.close();resolve(req.result||[]);};req.onerror=()=>{db.close();reject(req.error);};});}
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  function downloadJSON(value,name){downloadBlob(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),name);}
  function readFileBase64(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});}
  function fromBase64(value){const raw=atob(value),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes;}
  function toBase64(bytes){let out='';for(let i=0;i<bytes.length;i+=0x8000)out+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(out);}
  async function deriveKey(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
  async function buildEncryptedBackup(password){if(!crypto?.subtle)throw new Error('Web Crypto niedostępne. Użyj nowoczesnej przeglądarki przez HTTPS.');const docs=await getAllDocs();const total=docs.reduce((n,d)=>n+(d.blob?.size||0),0);if(total>MAX_BACKUP_DOCS)throw new Error(`Dokumenty mają ${fmt(total/1024/1024)} MB; limit kopii to 15 MB.`);const embedded=[];for(const d of docs){embedded.push({id:d.id,name:d.name,type:d.type,size:d.size,createdAt:d.createdAt,description:d.description||'',data:await readFileBase64(d.blob)});}const payload={schema:'NAUKA_OD_A_DO_Z_FIX43',build:BUILD,createdAt:now(),state,documents:embedded};const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveKey(password,salt),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(payload)));return `NP43ENC:${JSON.stringify({schema:'NP43ENC',version:1,kdf:'PBKDF2-SHA-256',iterations:310000,cipher:'AES-256-GCM',salt:toBase64(salt),iv:toBase64(iv),payload:toBase64(new Uint8Array(cipher))})}`;}
  async function restoreEncryptedBackup(raw,password){if(!crypto?.subtle)throw new Error('Web Crypto niedostępne.');if(!raw.startsWith('NP43ENC:'))throw new Error('To nie jest zaszyfrowana kopia FIX43.');const envelope=parse(raw.slice(8),null);if(!envelope||envelope.schema!=='NP43ENC'||envelope.version!==1||envelope.iterations!==310000)throw new Error('Nieprawidłowy format kopii.');const key=await deriveKey(password,fromBase64(envelope.salt));let plain;try{plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromBase64(envelope.iv)},key,fromBase64(envelope.payload));}catch{throw new Error('Nieprawidłowe hasło lub uszkodzona kopia.');}const data=parse(new TextDecoder().decode(plain),null);if(!data||data.schema!=='NAUKA_OD_A_DO_Z_FIX43')throw new Error('Kopia ma niezgodny schemat.');const next=normalizeState(data.state);await clearDocStore();for(const d of (Array.isArray(data.documents)?data.documents.slice(0,200):[])){if(!d||!d.id||typeof d.data!=='string')continue;const bytes=fromBase64(d.data);await putDoc({id:clean(d.id,80),name:clean(d.name,180),type:clean(d.type,100),size:bytes.byteLength,createdAt:clean(d.createdAt,40),description:clean(d.description,220),blob:new Blob([bytes],{type:clean(d.type,100)||'application/octet-stream'})});}state=next;state.documents=Array.isArray(data.documents)?data.documents.map(d=>({id:clean(d.id,80),name:clean(d.name,180),type:clean(d.type,100),size:Number(d.size)||0,createdAt:clean(d.createdAt,40),description:clean(d.description,220)})).filter(d=>d.id):[];persist();return true;}
  function evaluateAndSaveDiagnosis(input){const result=diagnoseBoard(input);const row={id:uid('DIA'),...result,device:clean(input.device,80),model:clean(input.model,140),boardId:clean(input.boardId,100),revision:clean(input.revision,50),symptom:clean(input.symptom,800),measurements:clean(input.measurements,1000),createdAt:now()};state.diagnoses.unshift(row);persist();return row;}
  function printEvidence(id){const item=state.evidence.find(x=>x.id===id);if(!item)return;const w=window.open('','_blank');if(!w){setStatus('Przeglądarka zablokowała okno raportu. Zezwól na wyskakujące okna dla tej strony.',true);return;}const html=`<!doctype html><html lang="pl"><meta charset="utf-8"><title>Raport naprawy ${esc(item.id)}</title><style>body{font:14px Arial;max-width:900px;margin:40px auto;color:#142437}h1{color:#124565}section{border:1px solid #ddd;padding:14px;margin:12px 0;border-radius:8px}small{color:#667}</style><h1>Raport naprawy / Nauka od A do Z</h1><p>${esc(item.id)} · ${esc(item.createdAt)}</p>${[['Urządzenie',item.device],['Model',item.model],['Board ID / rewizja',item.board],['Zlecenie',item.job],['Objaw',item.symptom],['Diagnoza / czynności',item.work],['Części',item.parts],['Wynik testu',item.result]].map(([a,b])=>`<section><b>${a}</b><p>${esc(b||'—').replace(/\n/g,'<br>')}</p></section>`).join('')}</html>`;w.document.write(html);w.document.close();setTimeout(()=>w.print(),350);}
  async function stopSerial(){serialStopped=true;try{await serialReader?.cancel();}catch{}try{serialReader?.releaseLock();}catch{}serialReader=null;try{await serialPort?.close();}catch{}serialPort=null;const s=$('#f43SerialState');if(s)s.textContent='Odczyt zatrzymany; port zamknięty.';const b=$('#f43SerialConnect');if(b)b.disabled=false;const st=$('#f43SerialStop');if(st)st.disabled=true;}
  async function startSerial(){const stateEl=$('#f43SerialState');if(!window.isSecureContext){stateEl.textContent='Web Serial wymaga bezpiecznego kontekstu HTTPS lub localhost.';return;}if(!('serial' in navigator)){stateEl.textContent='Ta przeglądarka nie udostępnia Web Serial. Możesz nadal zapisywać pomiary ręcznie.';return;}try{serialPort=await navigator.serial.requestPort();const baud=Number($('#f43Baud')?.value||9600);await serialPort.open({baudRate:baud});serialStopped=false;const decoder=new TextDecoderStream();serialPort.readable.pipeTo(decoder.writable).catch(()=>{});serialReader=decoder.readable.getReader();$('#f43SerialConnect').disabled=true;$('#f43SerialStop').disabled=false;stateEl.textContent=`Port otwarty (${baud} baud). Tryb wyłącznie odczytu — nic nie jest wysyłane.`;let buffer='';while(!serialStopped){const {value,done}=await serialReader.read();if(done)break;buffer+=value||'';const lines=buffer.split(/\r?\n/);buffer=lines.pop()||'';for(const line of lines){const parsed=parseSerialLine(line);const box=$('#f43SerialData');if(box)box.textContent=(line+'\n'+box.textContent).slice(0,1500);if(parsed){state.serialReadings.unshift({...parsed,at:now()});state.serialReadings=state.serialReadings.slice(0,50);persist();const list=$('#f43SerialReadings');if(list)list.innerHTML=renderSerialReadings();}}}}catch(error){stateEl.textContent=`Nie udało się otworzyć odczytu: ${clean(error?.message||error,220)}`;}finally{if(serialPort)await stopSerial();}}
  function bindHost(){if(!ROOT||ROOT.dataset.bound==='1')return;ROOT.dataset.bound='1';ROOT.addEventListener('click',async event=>{const button=event.target.closest('[data-f43-tab],[data-f43-open],[data-f43-doc-open],[data-f43-doc-delete],[data-f43-evidence-print],[data-f43-evidence-export],#f43SerialConnect,#f43SerialStop');if(!button)return;if(button.dataset.f43Tab){setTab(button.dataset.f43Tab);return;}if(button.dataset.f43Open){setTab(button.dataset.f43Open);return;}if(button.id==='f43SerialConnect'){startSerial();return;}if(button.id==='f43SerialStop'){await stopSerial();return;}if(button.dataset.f43DocOpen){try{const doc=await getDoc(button.dataset.f43DocOpen);if(!doc){setStatus('Nie odnaleziono pliku w lokalnej bibliotece.',true);return;}downloadBlob(doc.blob,doc.name);}catch(e){setStatus(e.message,true);}return;}if(button.dataset.f43DocDelete){try{await deleteDoc(button.dataset.f43DocDelete);state.documents=state.documents.filter(x=>x.id!==button.dataset.f43DocDelete);persist();render();setStatus('Dokument usunięto z lokalnej biblioteki.');}catch(e){setStatus(e.message,true);}return;}if(button.dataset.f43EvidencePrint){printEvidence(button.dataset.f43EvidencePrint);return;}if(button.dataset.f43EvidenceExport){const item=state.evidence.find(x=>x.id===button.dataset.f43EvidenceExport);if(item)downloadJSON(item,`${item.id}.json`);return;}});
    ROOT.addEventListener('input',event=>{if(event.target.id==='f43ComponentSearch'){const list=$('#f43ComponentList');if(list)list.innerHTML=renderComponents(event.target.value);}});
    ROOT.addEventListener('submit',async event=>{const form=event.target;if(!form.id.startsWith('f43'))return;event.preventDefault();try{
      if(form.id==='f43DoctorForm'){const v=Object.fromEntries(new FormData(form).entries());const result=evaluateAndSaveDiagnosis(v);$('#f43DoctorResult').innerHTML=`<div class="f43-result ${result.matched?'warn':'neutral'}"><h3>${esc(result.label)}</h3><p class="f43-muted">Pewność dopasowania edukacyjnego: ${Math.round(result.confidence*100)}%</p><h4>Możliwe kierunki sprawdzenia</h4><ul>${result.hypotheses.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Bezpieczna kolejność</h4><ol>${result.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>${esc(result.disclaimer)}</p></div>`;$('#f43DoctorHistory').innerHTML=renderDiagnosisList();setStatus('Analizę zapisano lokalnie.');return;}
      if(form.id==='f43SequenceForm'){const resultNode=$('#f43SequenceResult'),historyNode=$('#f43SequenceHistory');if(!resultNode||!historyNode)throw new Error('Laboratorium sekwencji jest niekompletne: brakuje panelu wyniku lub historii.');const v=Object.fromEntries(new FormData(form).entries());const result=evaluateSequence(v);const row={id:uid('SEQ'),...result,createdAt:now()};state.sequences.unshift(row);persist();resultNode.innerHTML=`<div class="f43-result ${result.level}"><h3>${esc(result.summary)}</h3><p>${esc(result.detail)}</p><ol>${result.sequence.map(x=>`<li><b>${esc(x.id)}</b>: ${x.status==='ok'?'zgodny':x.status==='missing'?'brak / niezgodny':'nie zmierzono'}</li>`).join('')}</ol></div>`;historyNode.innerHTML=state.sequences.slice(0,8).map(x=>`<article class="f43-list-row"><b>${esc(x.summary)}</b><small>${esc(x.createdAt)}</small><p>${esc(x.detail)}</p></article>`).join('');setStatus('Przebieg sekwencji zapisano lokalnie.');return;}
      if(form.id==='f43DocumentForm'){const file=$('#f43DocumentFile')?.files?.[0];if(!file)throw new Error('Wybierz dokument.');if(file.size>MAX_DOC)throw new Error('Plik przekracza limit 20 MB.');const allowed=/\.(pdf|csv|json|txt|jpe?g|png|webp)$/i.test(file.name);if(!allowed)throw new Error('Niedozwolony typ pliku.');const id=uid('DOC'),description=clean(new FormData(form).get('description'),220);await putDoc({id,name:clean(file.name,180),type:clean(file.type,100)||'application/octet-stream',size:file.size,createdAt:now(),description,blob:file});state.documents.unshift({id,name:clean(file.name,180),type:clean(file.type,100),size:file.size,createdAt:now(),description});persist();render();setStatus('Dokument zapisany lokalnie w IndexedDB — dostępny bez Internetu na tym urządzeniu.');return;}
      if(form.id==='f43ComponentForm'){const v=Object.fromEntries(new FormData(form).entries());const id=clean(v.id,80);if(SEED_COMPONENTS.some(x=>x.id.toLowerCase()===id.toLowerCase())||state.components.some(x=>x.id.toLowerCase()===id.toLowerCase()))throw new Error('Element o tym ID już istnieje.');state.components.unshift({id,name:clean(v.name,120),category:clean(v.category,80),package:clean(v.package,60),notes:clean(v.notes,600),source:clean(v.source,300)});persist();render();setStatus('Element dodano do lokalnego katalogu.');return;}
      if(form.id==='f43EvidenceForm'){const v=Object.fromEntries(new FormData(form).entries());const files=[...($('#f43EvidenceFiles')?.files||[])];const attachments=[];for(const file of files.slice(0,8)){if(file.size>MAX_DOC)continue;const id=uid('EVD');await putDoc({id,name:clean(file.name,180),type:clean(file.type,100),size:file.size,createdAt:now(),description:'Załącznik do raportu naprawy',blob:file});state.documents.unshift({id,name:clean(file.name,180),type:clean(file.type,100),size:file.size,createdAt:now(),description:'Załącznik do raportu naprawy'});attachments.push(id);}const row={id:uid('RPT'),device:clean(v.device,80),model:clean(v.model,140),board:clean(v.board,120),job:clean(v.job,60),symptom:clean(v.symptom,500),work:clean(v.work,1800),parts:clean(v.parts,800),result:clean(v.result,1000),attachments,createdAt:now()};state.evidence.unshift(row);persist();render();setStatus('Raport naprawy i lokalne załączniki zapisane.');return;}
      if(form.id==='f43BuildForm'){const result=checkBuild(Object.fromEntries(new FormData(form).entries()));state.buildChecks.unshift({id:uid('PC'),...result,createdAt:now()});persist();$('#f43BuildResult').innerHTML=`<div class="f43-result ${result.compatible?'good':'warn'}"><h3>${result.compatible?'Brak wykrytych konfliktów w podanych parametrach':'Wykryto niezgodności'}</h3>${result.issues.length?`<ul>${result.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${result.warnings.length?`<ul>${result.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p>${esc(result.notice)}</p></div>`;setStatus('Wynik kompatybilności zapisano lokalnie.');return;}
      if(form.id==='f43BackupForm'){const v=Object.fromEntries(new FormData(form).entries());if(v.password!==v.confirm)throw new Error('Hasła nie są identyczne.');if(v.password.length<12)throw new Error('Hasło musi mieć minimum 12 znaków.');const data=await buildEncryptedBackup(v.password);downloadBlob(new Blob([data],{type:'application/octet-stream'}),`NAUKA_FIX43_BACKUP_${new Date().toISOString().slice(0,10)}.np43`);$('#f43BackupStatus').textContent='Kopia została zaszyfrowana i pobrana. Zachowaj hasło — nie można go odzyskać.';return;}
      if(form.id==='f43RestoreForm'){const v=Object.fromEntries(new FormData(form).entries());const file=$('#f43RestoreForm input[type=file]')?.files?.[0];if(!file)throw new Error('Wybierz plik kopii.');if(file.size>MAX_BACKUP_DOCS*2+2*1024*1024)throw new Error('Plik kopii przekracza dozwolony rozmiar.');const raw=await file.text();await restoreEncryptedBackup(raw,v.password);render();$('#f43RestoreStatus').textContent='Kopia odszyfrowana i przywrócona. Odświeżono dane FIX43.';setStatus('Przywracanie kopii zakończone.');return;}
    }catch(error){setStatus(error.message||'Operacja nie powiodła się.',true);const target=form.querySelector('[id$="Status"]');if(target)target.textContent=error.message||'Operacja nie powiodła się.';}});
  }
  function renderFeedbackHistory(){const host=document.getElementById('f43FeedbackHistory');if(!host)return;const rows=parse(localStorage.getItem(FEEDBACK_STORE),[]);host.innerHTML=rows.slice(0,20).map(x=>`<article class="f43-list-row"><b>Ocena: ${x.rating}/5 ${'★'.repeat(x.rating)}</b><small>${esc(x.createdAt)} · ${x.sent?'przekazano do serwera':'zapis lokalny / oczekuje'}</small>${x.whatAdd?`<p><b>Do dodać:</b> ${esc(x.whatAdd)}</p>`:''}${x.whatChange?`<p><b>Zmienić:</b> ${esc(x.whatChange)}</p>`:''}${x.whatBroken?`<p><b>Nie działa:</b> ${esc(x.whatBroken)}</p>`:''}${x.details?`<p>${esc(x.details)}</p>`:''}</article>`).join('')||'<p class="f43-muted">Brak zapisanych opinii.</p>';}
  async function initFeedback(){if(!FEEDBACK_PAGE||FEEDBACK_PAGE.dataset.f43Bound==='1')return;FEEDBACK_PAGE.dataset.f43Bound='1';const form=$('#f43FeedbackForm',FEEDBACK_PAGE);const route=$('#f43FeedbackRoute',FEEDBACK_PAGE);if(route)route.value=location.pathname+location.search;renderFeedbackHistory();
    form?.addEventListener('submit',async event=>{event.preventDefault();const v=Object.fromEntries(new FormData(form).entries());const rating=Number(v.rating);if(!Number.isInteger(rating)||rating<1||rating>5){FEEDBACK_STATUS.textContent='Wybierz ocenę od 1 do 5.';return;}const whatAdd=clean(v.whatAdd,1500),whatChange=clean(v.whatChange,1500),whatBroken=clean(v.whatBroken,1500),details=clean(v.details,1500);if(!whatAdd&&!whatChange&&!whatBroken&&!details){FEEDBACK_STATUS.textContent='Dodaj przynajmniej jedną uwagę.';return;}if(v.consent!=='on'){FEEDBACK_STATUS.textContent='Zaznacz zgodę na przekazanie opinii.';return;}const row={id:uid('FB'),rating,whatAdd,whatChange,whatBroken,details,route:clean(v.route,220),createdAt:now(),sent:false};const rows=parse(localStorage.getItem(FEEDBACK_STORE),[]);rows.unshift(row);localStorage.setItem(FEEDBACK_STORE,JSON.stringify(rows.slice(0,50)));renderFeedbackHistory();FEEDBACK_STATUS.textContent='Opinia zapisana lokalnie. Próbuję przekazać ją do kolejki administratora…';try{const response=await fetch('/api/site-feedback',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({rating,whatAdd,whatChange,whatBroken,details,route:row.route,consent:true})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.message||result.error||`HTTP ${response.status}`);row.sent=true;row.serverId=result.id;localStorage.setItem(FEEDBACK_STORE,JSON.stringify(rows.slice(0,50)));FEEDBACK_STATUS.textContent='Dziękujemy! Opinia została zapisana lokalnie i przekazana do kolejki administratora.';}catch(error){FEEDBACK_STATUS.textContent=`Opinia jest bezpiecznie zapisana lokalnie, ale wysłanie do serwera nie powiodło się (${clean(error.message,160)}). Możesz pobrać JSON i przekazać go ręcznie.`;}renderFeedbackHistory();form.reset();if(route)route.value=location.pathname+location.search;});
    $('#f43ExportFeedback',FEEDBACK_PAGE)?.addEventListener('click',()=>downloadJSON(parse(localStorage.getItem(FEEDBACK_STORE),[]),'moje-opinie-nauka-od-a-do-z.json'));
    $('#f43CopyFeedback',FEEDBACK_PAGE)?.addEventListener('click',async()=>{const row=parse(localStorage.getItem(FEEDBACK_STORE),[])[0];if(!row){FEEDBACK_STATUS.textContent='Nie ma jeszcze zgłoszenia do skopiowania.';return;}const txt=[`Ocena: ${row.rating}/5`,`Co dodać: ${row.whatAdd}`,`Co zmienić: ${row.whatChange}`,`Co nie działa: ${row.whatBroken}`,`Opis: ${row.details}`,`Widok: ${row.route}`,`Data: ${row.createdAt}`].join('\n');try{await navigator.clipboard.writeText(txt);FEEDBACK_STATUS.textContent='Ostatnie zgłoszenie skopiowane.';}catch{downloadBlob(new Blob([txt],{type:'text/plain'}),'ostatnie-zgloszenie.txt');FEEDBACK_STATUS.textContent='Schowek niedostępny — pobrano plik TXT.';}});
    $('#f43LoadAdminFeedback',FEEDBACK_PAGE)?.addEventListener('click',async()=>{const token=$('#f43AdminToken',FEEDBACK_PAGE)?.value||'';const host=$('#f43AdminFeedbackList',FEEDBACK_PAGE);if(!token){host.textContent='Wpisz token administratora.';return;}host.textContent='Pobieranie…';try{const res=await fetch('/api/admin/site-feedback',{headers:{authorization:`Bearer ${token}`},credentials:'same-origin'});const data=await res.json();if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);host.innerHTML=(data.items||[]).map(x=>`<article class="f43-list-row"><b>${x.rating}/5 · ${esc(x.status)} · ${esc(x.route)}</b><small>${esc(x.created_at)} · ${x.user_id?'konto':'anonimowo'}</small><p><b>Do dodać:</b> ${esc(x.what_add)}</p><p><b>Zmienić:</b> ${esc(x.what_change)}</p><p><b>Nie działa:</b> ${esc(x.what_broken)}</p><p>${esc(x.details)}</p><div class="f43-actions"><button type="button" class="f43-btn secondary" data-f43-admin-status="in_review" data-f43-admin-id="${esc(x.id)}">W trakcie</button><button type="button" class="f43-btn secondary" data-f43-admin-status="fixed" data-f43-admin-id="${esc(x.id)}">Naprawione</button><button type="button" class="f43-btn secondary" data-f43-admin-status="wont_fix" data-f43-admin-id="${esc(x.id)}">Odrzuć</button></div></article>`).join('')||'<p class="f43-muted">Brak opinii.</p>';host.dataset.loaded='1';}catch(e){host.textContent=`Nie udało się pobrać opinii: ${clean(e.message,180)}`;}});
    $('#f43AdminFeedbackList',FEEDBACK_PAGE)?.addEventListener('click',async event=>{const btn=event.target.closest('[data-f43-admin-status]');if(!btn)return;const token=$('#f43AdminToken',FEEDBACK_PAGE)?.value||'';try{const res=await fetch('/api/admin/site-feedback',{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${token}`},credentials:'same-origin',body:JSON.stringify({id:btn.dataset.f43AdminId,status:btn.dataset.f43AdminStatus})});const data=await res.json();if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);btn.closest('.f43-list-row')?.remove();}catch(e){alert(`Nie udało się zmienić statusu: ${clean(e.message,160)}`);}});
  }
  function initNavShortcut(){document.querySelectorAll('[data-f43-open]').forEach(()=>{});}
  bindHost();if(ROOT)render();initFeedback();initNavShortcut();
  const API=Object.freeze({build:BUILD,normalizeState,diagnoseBoard,evaluateAndSaveDiagnosis,evaluateSequence,parseSerialLine,checkBuild,renderGraph:()=>renderGraph(),getState:()=>JSON.parse(JSON.stringify(state)),getCases:()=>CASES.map(x=>x.id),getSignals:()=>SIGNALS.map(x=>x[0]),encryptBackup:buildEncryptedBackup,restoreBackup:restoreEncryptedBackup,setTab,render});
  window.NP_NAUKA_FIX43=API;
  if(PAGE)setStatus('Centrum Wiedzy FIX43 gotowe. Dokumenty i historia są lokalne; połączenie sprzętowe ma tryb odczytu.');
  renderFeedbackHistory();
})();
